declare(strict_types=1);
if(!defined('CMS_ENTRY'))exit;
function panel(string $title,string $body,int $status=200):never{http_response_code($status);header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'.e($title).' — 1DED Free CMS</title><link rel="stylesheet" href="'.e(local_url('/assets/admin.css')).'"><style>body{background:#f0f4ed}.install{max-width:900px;margin:50px auto;padding:35px;background:#fff;border:1px solid #d1ddcf;border-radius:20px}.install h1{font-size:36px;margin:20px 0}.install h2{margin:25px 0 15px}.install p{line-height:1.7;margin:15px 0}.install .form-grid{margin-top:20px}.install pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px;background:#eaf2e5}.install li{margin-bottom:8px}.install code{overflow-wrap:anywhere}.install .check{display:flex}.install small{display:block}.install table{width:100%;margin:20px 0}</style></head><body><main class="install"><small>1DED FREE CMS · PHP EDITION · VERSION 1.0</small><h1>'.e($title).'</h1>'.$body.'</main></body></html>';exit;}
function install_session():void{if(session_status()!==PHP_SESSION_ACTIVE){ini_set('session.use_strict_mode','1');session_name('cms_php_install');session_set_cookie_params(['path'=>base_path().'/','secure'=>tls(),'httponly'=>true,'samesite'=>'Strict']);session_start();}if(empty($_SESSION['nonce'])||($_SESSION['nonce_time']??0)<time()-1800){$_SESSION['nonce']=bin2hex(random_bytes(32));$_SESSION['nonce_time']=time();}}
function web_install():never{
 if(config())panel('Already installed','<p>The installer is locked. <a href="'.e(local_url('/admin/')).'">Open your admin panel</a>.</p>',409);
 if(!tls()&&!localhost_request())panel('HTTPS is required','<p>Enable SSL for this domain in your hosting control panel, then open the installer over HTTPS.</p>',400);
 install_session();$keyPath=__DIR__.'/INSTALL-KEY.txt';if(!is_file($keyPath)){$handle=@fopen($keyPath,'x');if($handle){chmod($keyPath,0600);fwrite($handle,bin2hex(random_bytes(32)));fclose($handle);}}
 $drivers=PDO::getAvailableDrivers();$checks=['PHP 8.3 or newer'=>PHP_VERSION_ID>=80300,'PDO MySQL or SQLite'=>in_array('mysql',$drivers,true)||in_array('sqlite',$drivers,true),'ZIP archives'=>class_exists('ZipArchive'),'File type inspection'=>extension_loaded('fileinfo'),'GD image decoding'=>extension_loaded('gd'),'Multibyte text'=>extension_loaded('mbstring'),'OpenSSL'=>extension_loaded('openssl'),'Writable app directory'=>is_writable(__DIR__)];$ready=!in_array(false,$checks,true);$error='';
 if($_SERVER['REQUEST_METHOD']==='POST'){
  try{if(strtolower($_SERVER['HTTP_ORIGIN']??'')!==request_origin())fail(403,'Cross-origin installation blocked.');if(!hash_equals($_SESSION['nonce'],(string)($_POST['nonce']??'')))fail(403,'Refresh the installer and try again.');$_SESSION['attempts']=($_SESSION['attempts']??0)+1;if($_SESSION['attempts']>10)fail(429,'Too many installer attempts. Reopen your browser session later.');if(!$ready)fail(400,'Fix the hosting requirements before installing.');$key=trim((string)@file_get_contents($keyPath));if(!$key||!hash_equals($key,trim((string)($_POST['token']??''))))fail(403,'Installation key is incorrect. Read app/INSTALL-KEY.txt in File Manager.');
   $private=trim((string)($_POST['private']??''));if(!$private||str_contains($private,"\0"))fail(400,'Choose a private storage directory.');if(!is_dir($private)&&!@mkdir($private,0700,true))fail(400,'Cannot create private storage. Use a writable path outside public_html.');$private=realpath($private);$doc=realpath($_SERVER['DOCUMENT_ROOT']??CMS_ROOT);if(!$private||!$doc||inside($doc,$private)||inside(realpath(CMS_ROOT),$private))fail(400,'Storage must be outside the public document root.');chmod($private,0700);$lock=write_lock($private);if(is_file(__DIR__.'/installed.php')||is_file($private.'/config.php'))fail(409,'This installation is already configured.');
   $driver=choose($_POST['driver']??'',['mysql','sqlite'],'mysql');if(!in_array($driver,$drivers,true))fail(400,'This database driver is unavailable.');$c=['driver'=>$driver,'private'=>$private,'url'=>request_origin().base_path(),'host'=>txt($_POST['host']??'localhost',255),'port'=>(int)($_POST['port']??3306),'database'=>txt($_POST['database']??'',64),'username'=>txt($_POST['username']??'',100),'password'=>(string)($_POST['dbpassword']??'')];if($driver==='mysql'&&(!preg_match('/^[A-Za-z0-9.:-]+$/D',$c['host'])||!preg_match('/^[A-Za-z0-9_$-]{1,64}$/D',$c['database'])||$c['port']<1||$c['port']>65535))fail(400,'Check the database host, name and port.');
   $email=strtolower(txt($_POST['email']??'',254));if(!filter_var($email,FILTER_VALIDATE_EMAIL))fail(400,'Enter a valid owner email.');$hash=password_make($_POST['password']??'');if(!hash_equals((string)($_POST['password']??''),(string)($_POST['confirm']??'')))fail(400,'Passwords do not match.');$recovery=bin2hex(random_bytes(24));$db=database($c);schema($db);if((int)$db->query('SELECT count(*) FROM cms_users')->fetchColumn()>0)fail(409,'This database already contains a CMS. Choose a dedicated empty database.');
   $bundle=starter(txt($_POST['preset']??'company',80));$site=array_merge(default_site(),$bundle['settings'],['menus'=>$bundle['menus'],'footerMenus'=>$bundle['footerMenus'],'name'=>txt($_POST['name']??'',200),'url'=>$c['url']]);$site['copyright']=$site['name'];$pages=[];foreach($bundle['pages'] as $p)$pages[]=validate_page($p,$bundle['pages'],$bundle['categories']);$site=validate_site($site,$pages,$bundle['categories']);$initial=['schema'=>CMS_SCHEMA,'site'=>$site,'pages'=>$pages,'categories'=>$bundle['categories'],'links'=>[],'redirects'=>[],'media'=>[],'trash'=>[],'history'=>[],'messages'=>[],'audit'=>[],'revisions'=>[],'current'=>null,'schedule'=>null,'autosave'=>true,'starterImports'=>[['id'=>uid(),'starterId'=>$bundle['definition']['id'],'name'=>$bundle['definition']['name'],'prefix'=>'','created'=>stamp(),'pageIds'=>array_column($pages,'id')]]];
   $db->beginTransaction();try{$q=$db->prepare('INSERT INTO cms_kv(name,value) VALUES (?,?)');foreach($initial as $k=>$v)$q->execute([$k,json_encode($v,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$q=$db->prepare('INSERT INTO cms_users VALUES (?,?,?,?,?)');$q->execute([uid(),$email,$hash,'owner',password_hash($recovery,PASSWORD_DEFAULT)]);}catch(Throwable $ex){$db->rollBack();throw $ex;}
   foreach(['media','originals','releases','backups'] as $d)if(!is_dir($private.'/'.$d))mkdir($private.'/'.$d,0700);atomic_write($private.'/.htaccess',"Require all denied\n");$createdConfig=true;atomic_write($private.'/config.php',"<?php\nif(!defined('CMS_ENTRY'))exit;\nreturn ".var_export($c,true).";\n");$createdPointer=true;atomic_write(__DIR__.'/installed.php',"<?php\nif(!defined('CMS_ENTRY'))exit;\nreturn ".var_export($private.'/config.php',true).";\n");$db->commit();@unlink($keyPath);$_SESSION=[];session_destroy();
   panel('Your studio is ready','<p>Your owner account has been created. Keep this recovery code somewhere private. It is displayed once and lets you reset the owner password without SSH or email.</p><pre>'.e($recovery).'</pre><p>Anyone with this code and your email can reset access. A successful recovery rotates the code and revokes every account session.</p><p><a class="btn primary" href="'.e(local_url('/admin/')).'">Open admin panel</a></p><p>The installer is now locked. Your templates are ready; review the example content before publishing.</p>');
  }catch(CmsError $ex){install_cleanup($db??null,$private??'',$createdConfig??false,$createdPointer??false);$error=$ex->getMessage();}catch(PDOException $ex){install_cleanup($db??null,$private??'',$createdConfig??false,$createdPointer??false);error_log('1DED install database error: '.$ex->getCode());$error='Database setup failed. Check the hosting database details and use a dedicated empty database.';}catch(Throwable $ex){install_cleanup($db??null,$private??'',$createdConfig??false,$createdPointer??false);error_log('1DED install: '.$ex->getMessage());$error='Installation could not finish. Check file permissions and the PHP error log.';}
 }
 $body='<p>Upload and extract the PHP edition using cPanel or DirectAdmin File Manager. No Node.js, Composer or shell access is needed. Use a currently patched PHP version; Apache 2.4 or compatible LiteSpeed must honour the included .htaccess rules.</p><h2>Hosting checks</h2><ul>';foreach($checks as $name=>$ok)$body.='<li>'.($ok?'✓ ':'✗ ').e($name).'</li>';$body.='</ul>';if($error)$body.='<div class="notice error" role="alert">'.e($error).'</div>';
 $body.='<form method="post"><input type="hidden" name="nonce" value="'.e($_SESSION['nonce']).'"><h2>Confirm control of the hosting account</h2><p>In File Manager, open <code>app/INSTALL-KEY.txt</code> and paste its contents below. This file is blocked from web access. Do not share the key.</p><label>Installation key<input name="token" required autocomplete="off"></label><h2>Storage and database</h2><label>Private storage path<input name="private" value="'.e(private_default()).'" required><small>Must be outside all public website folders, including public_html and addon-domain document roots.</small></label><label>Database type<select name="driver">'.(in_array('mysql',$drivers,true)?'<option value="mysql">MySQL / MariaDB — normal shared hosting</option>':'').(in_array('sqlite',$drivers,true)?'<option value="sqlite">SQLite — no database account required</option>':'').'</select></label><p>For MySQL/MariaDB, create a database and assign its user in your hosting control panel. Include the account prefix in database and username. SQLite ignores these fields.</p><div class="form-grid"><label>Database host<input name="host" value="localhost"></label><label>Database port<input name="port" type="number" value="3306"></label><label>Database name<input name="database" autocomplete="off"></label><label>Database username<input name="username" autocomplete="off"></label><label>Database password<input name="dbpassword" type="password" autocomplete="new-password"></label></div><h2>Website and owner</h2><label>Website name<input name="name" required maxlength="200" value="My Website"></label><label>Website starter<select name="preset">';foreach(catalog()['starters'] as $s)$body.='<option value="'.e($s['id']).'"'.($s['id']==='company'?' selected':'').'>'.e($s['name']).'</option>';$body.='</select></label><label>Owner email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Confirm password<input name="confirm" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><p><button class="btn primary"'.(!$ready?' disabled':'').'>Create my website</button></p></form>';panel('Install your own website',$body);
}
function web_recovery(Store $store):never{install_session();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{origin_check();if(!hash_equals($_SESSION['nonce'],(string)($_POST['nonce']??'')))fail(403,'Refresh this page and try again.');limited($store,'recovery',5,3600);$email=strtolower(txt($_POST['email']??'',254));$u=$store->query('SELECT * FROM cms_users WHERE email=? AND role=?',[$email,'owner'])->fetch();$code=txt($_POST['code']??'',100);$valid=password_verify($code,$u['recovery']??'$2y$12$1FcTLjHn.kRXRY1j2QHVA.gqVsuNtf1zHftYhk8PloM8eQxeGX8wS');if(!$u||!$valid)fail(400,'Email or recovery code is incorrect.');$hash=password_make($_POST['password']??'');if(($_POST['password']??'')!==($_POST['confirm']??''))fail(400,'Passwords do not match.');$next=bin2hex(random_bytes(24));$store->tx(function()use($store,$u,$hash,$next){$store->query('UPDATE cms_users SET hash=?,recovery=? WHERE id=?',[$hash,password_hash($next,PASSWORD_DEFAULT),$u['id']]);$store->query('DELETE FROM cms_sessions WHERE user_id=?',[$u['id']]);save_security($store,$u['id'],[]);clear_challenges($store,$u['id']);$store->audit($u['email'],'Recovered owner access and rotated recovery code');});session_cookie('',0);panel('Access recovered','<p>Your password was changed and all account sessions were revoked. Your old recovery code no longer works. Save this replacement code privately:</p><pre>'.e($next).'</pre><a class="btn primary" href="'.e(local_url('/admin/')).'">Sign in</a>');}catch(CmsError $ex){$error=$ex->getMessage();}}
 panel('Recover owner access',($error?'<div class="notice error">'.e($error).'</div>':'').'<p>Use the private recovery code you saved during installation. This does not send email or require server access. If you have lost the code, recovery requires a verified hosting-account maintenance procedure; the CMS does not bypass ownership checks.</p><form method="post"><input type="hidden" name="nonce" value="'.e($_SESSION['nonce']).'"><label>Owner email<input type="email" name="email" required></label><label>Recovery code<input name="code" required autocomplete="off"></label><label>New password<input type="password" name="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm" required minlength="12" maxlength="72" autocomplete="new-password"></label><button class="btn primary">Recover my account</button></form>');}

function install_cleanup(?PDO $db,string $private,bool $config,bool $pointer):void{if($db&&$db->inTransaction())$db->rollBack();if($pointer&&is_file(__DIR__.'/installed.php'))unlink(__DIR__.'/installed.php');if($config&&$private&&is_file($private.'/config.php'))unlink($private.'/config.php');}
